-- Resources content for the project and Pieces screens on a phone (CLAUDE.md, "Resources stay in step
-- with the code"). Content only; no schema. Depends on 20261031120000. The Pieces tab no longer offers a
-- format before + New piece (the editor's Format control is the one place), the project's row of steps
-- fits one line on a phone, the title and ⋮ share a line, and the next-step panel is shorter.

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or feature block by block, or outline it from your findings, then edit by hand or with the assistant. Every version is kept.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'The format is chosen in the editor',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project's excerpts. It starts blank. You can write it block by block, or let AI outline it from your accepted findings, write the outline out as narration, and then edit it by hand or with the assistant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type. The Pieces list shows each piece's length and when it last changed."}]},{"type":"paragraph","content":[{"type":"text","text":"A format sets the piece's target length and gives you a guide to write by. Choose one, or change it, any time from "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" under the length at the top of the piece, and "},{"type":"text","text":"Show guide","marks":[{"type":"bold"}]},{"type":"text","text":" shows its description. The guide is a reminder of what the format usually asks for; it doesn't stop you doing something else. Choosing a format doesn't change what you've written."}]},{"type":"paragraph","content":[{"type":"text","text":"The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline and write it out (optional)"}]},{"type":"paragraph","content":[{"type":"text","text":"On an empty piece, choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":". It plans the story as beats, with your excerpts placed where they belong, from the findings you have accepted. A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":", which turns each beat into narration in place. Both are versions you can undo, and nothing is written until you ask. The Outline a piece guide has the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose Excerpt to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Mark as anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" (on narration), "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" is the lead-in the anchor reads before a reporter's recorded piece. It is shown as its own block and isn't counted in the piece's length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time, without any anchor intro. Choosing a format sets a target; select "},{"type":"text","text":"Change target","marks":[{"type":"bold"}]},{"type":"text","text":" to use a different one. The piece shows how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask the assistant"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the assistant from "},{"type":"text","text":"Assistant","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or outline the piece again. Anything you have typed is saved before your message goes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It changes only what you ask, and says what it changed. Its reply lists the tools it used."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It places and swaps excerpts by id. It can't change what a speaker said, and the lengths it reports come from the same arithmetic as the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each block it changed is marked "},{"type":"text","text":"Edited by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Added by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on the mark puts that block back. The marks stay until you next edit the piece yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a + row, Ask the assistant to write it opens the assistant with a request for narration at that spot, for you to finish and send."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every outline or write-out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists the versions with who saved each one, and whether it was you, an outline or a write-out, or the assistant. Restore saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outlining, writing out and the assistant send the piece's material (accepted findings and the excerpts' words) to an outside service, as analysis does. Building a piece by hand doesn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Pieces list says how each piece was made: Written by hand, or the format it was written from, then edited."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-project-overview',
  p_tool_key => 'transcription',
  p_title => 'A project at a glance',
  p_summary => 'See where a project stands, do the next step yourself or with AI, and find any source.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 12,
  p_version_note => 'The steps fit one line on a phone',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The steps and the next step"}]},{"type":"paragraph","content":[{"type":"text","text":"The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" when sources are ready, "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" when findings and clips are waiting, then Open Synthesis and Start a piece. The steps only report and suggest. You can use any tab at any time. On a phone the row shows the step numbers and names only the current step; a finished step's number still opens its tab."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tabs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" holds what you browse. Sources lists the project's sources, Data points lists the findings you have accepted or rejected, and Excerpts lists the excerpts made from them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" is where you decide on the findings and clips that Analyze suggested. The number beside it is how many are waiting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis, Pieces and Setup work as before."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run the remaining steps with AI"}]},{"type":"paragraph","content":[{"type":"text","text":"The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. Stop after this step ends the run, and what finished is kept."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filter sources searches titles. Show narrows the list to sources not yet analyzed or that need attention, and Sort puts the newest first or sorts by title. The list shows 25 at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ Add source sits with the filters above the source list. The ⋮ menu at the top of the page edits the background or deletes the project, with a list of what goes and what stays."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hints that go away"}]},{"type":"paragraph","content":[{"type":"text","text":"Short how-to notes on some screens, such as how to select words into an excerpt, show a Got it button. Select it and that note stays hidden in this browser."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-01-sourcework-phone-screens',
  p_tool_key => 'transcription',
  p_released_on => '2026-11-01',
  p_title => 'Sourcework: a project and its Pieces list fit a phone better',
  p_guide_slugs => array['sourcework-project-overview', 'sourcework-pieces'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a phone, a project's title and its ⋮ menu now share one line, the row of steps fits one line with only the current step named, and the next-step panel is shorter, with its button and the hand-over link side by side. The Pieces tab no longer asks for a format before + New piece: choose the format in the editor, under the piece's length, where its guide is. Two controls in a toolbar share a row at half width even when their form carries a hidden field, and every page leaves room under its last row for the assistant button."}]}]}$body$
);
